CREATE FUNCTION public.can_read_pyq_file(_path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.pyqs q WHERE q.file_path=_path AND (public.can_upload_pyq(q.class_id,q.subject_id) OR (public.has_role(auth.uid(),'student') AND EXISTS(SELECT 1 FROM public.students p JOIN public.sections s ON s.id=p.section_id WHERE p.profile_id=auth.uid() AND p.active AND s.class_id=q.class_id)))) $$;
ALTER POLICY pyq_files_read ON storage.objects USING(bucket_id='school-pyqs' AND (public.has_role(auth.uid(),'super_admin') OR (owner_id=auth.uid()::text AND public.has_role(auth.uid(),'teacher')) OR public.can_read_pyq_file(name)));